import React from "react";
import { Audio, Sequence, staticFile } from "remotion";

export type SfxName =
  | "chime"
  | "tick"
  | "page"
  | "ready"
  | "press"
  | "droplet"
  | "sparkle"
  | "bloom"
  | "pop"
  | "whoosh"
  | "boop1"
  | "boop2"
  | "boop3"
  | "boop4"
  | "riser";

type Props = {
  /** Sound name — a WAV in public/sfx/ generated by scripts/gen-sfx.mjs. */
  name: SfxName;
  /** Scene-relative frame at which the sound fires. */
  at?: number;
  volume?: number;
};

/**
 * A cuelume UI sound mounted at an exact frame. The WAVs are pre-rendered
 * from cuelume's synth recipes (Remotion cannot capture live Web Audio),
 * peak-normalized to -12 dBFS.
 */
export const Sfx: React.FC<Props> = ({ name, at = 0, volume = 0.7 }) => (
  <Sequence from={at} layout="none">
    <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
  </Sequence>
);
